window.kbPageData["views/entry/k-093f295fb9a01792"] = {"key":"entry/k-093f295fb9a01792","state":{"route":"entry/k-093f295fb9a01792"},"node":{"id":"k-093f295fb9a01792","mode":"k","title":"“十四五”时期经济社会发展成就","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["modern"],"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["政治理论"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"二、“十四五”时期经济社会发展成就\n2025 年是“十四五”收官之年。过去 5 年，以习近平同志为核心的党中央团结带领全\n国各族人民，有效应对世纪疫情等超乎寻常的冲击挑战，推动党和国家事业取得新的重大成\n就，第二个百年奋斗目标新征程实现良好开局。\n经济总量实现新跃升，国内生产总值连续跨越 110 万…","sources":[{"id":"9435ea99da8190a1","label":"“十四五”时期经济社会发展成就","topic":"年度政府工作","category":"时政","text":"二、“十四五”时期经济社会发展成就\n2025 年是“十四五”收官之年。过去 5 年，以习近平同志为核心的党中央团结带领全\n国各族人民，有效应对世纪疫情等超乎寻常的冲击挑战，推动党和国家事业取得新的重大成\n就，第二个百年奋斗目标新征程实现良好开局。\n经济总量实现新跃升，国内生产总值连续跨越 110 万亿元、120 万亿元、130 万亿元、\n140 万亿元台阶，年均增长 5.4%、明显高于全球平均增速。科技和产业创新取得新突破，全\n社会研发经费投入年均增长 10%，每万人口高价值发明专利拥有量达到 16 件，攻克一批重\n大关键核心技术，制造业增加值规模连续 16 年保持全球第一，产业链供应链韧性和安全水\n平稳步提升。改革开放迈出新步伐，重点领域改革扎实推进，全国统一大市场加快构建，高\n水平对外开放不断扩大，制造业领域外资准入限制措施全部取消，货物贸易第一大国地位更\n加巩固，高质量共建“一带一路”走深走实。民生福祉达到新水平，居民人均可支配收入年\n均增长 5.4%，城镇新增就业累计超过 6000 万人，巩固拓展脱贫攻坚成果同乡村振兴有效衔\n接 5 年过渡期任务圆满完成，脱贫地区农村居民收入增速持续高于全国农村平均水平，基本\n养老保险全国统筹稳步实施，劳动年龄人口平均受教育年限增加到 11.3 年，人均预期寿命\n提高到 79.25 岁，人民群众文化生活更加丰富多彩。生态文明建设取得新进步，地级及以上\n城市空气质量优良天数比例提高到 89.3%，森林覆盖率提高到 25%以上，成为全球森林资源\n增长最快最多的国家，构建起全球最大、发展最快的可再生能源体系。安全保障能力实现\n新提升，粮食、能源资源、金融、网络等重点领域安全能力建设明显加强，社会大局保持稳\n定，牢牢守住了不发生系统性风险底线。经过艰苦奋斗、不懈努力，“十四五”规划《纲要》\n确定的 20 项主要指标、17 方面重大战略任务、102 项重大工程项目胜利完成。\n这些重大成就的取得，根本在于以习近平同志为核心的党中央领航掌舵，在于习近平新\n时代中国特色社会主义思想科学指引，是全党全军全国各族人民团结奋斗的结果。\n在肯定成绩的同时，我们也清醒看到面临的困难和挑战。外部环境变化影响加深，地缘\n政治风险持续上升，世界经济动能疲弱，多边主义、自由贸易受到严重冲击。国内经济发展\n和转型中面临的老问题、新挑战仍然不少。困难不容忽视，信心必须坚定。我国经济长期向\n好的支撑条件和基本趋势没有改变，制度优势和大国优势不断彰显。经历了风雨洗礼，我\n们的意志更加坚强、步伐更加坚定，只要用足用好优势、妥善应对挑战，我国的发展前景一\n定更加可期！","source":{"doc":"6cbfb01fe723bba64b75","first":14,"last":14,"page":14,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"}],"units":{"k-093f295fb9a01792":[]}};
